validator:
function validate(input) {
  const [{ products = [] }] = input;
  for (const [name, , price] of products) {
    if (name === null) return 'Every product needs a name.';
    if (price === null) return 'price cannot be null.';
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = ['Wristwatch', 'WirelessEarbuds', 'GolfClubs', 'Printer', 'Laptop', 'Camera'];
  const counts = [0, 1, 5, 779, 849];
  const rows = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const products = [];
  for (let i = 0; i < rows; i++) {
    const name = size === 'small' ? pick(names) : `${pick(names)}${i}`;
    const quantity = rand() < 0.35 ? null : size === 'small' ? pick(counts) : Math.floor(rand() * 1000);
    products.push([name, quantity, Math.floor(rand() * 10000) + 1]);
  }
  return [{ products }];
}
